package br.com.locago.atendimento;
import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.List;import java.util.Map;
@Service public class ServicoCatalogoService{
 private final JdbcClient jdbc;public ServicoCatalogoService(JdbcClient jdbc){this.jdbc=jdbc;}
 public List<Map<String,Object>> listar(){return jdbc.sql("select id,nome,natureza,valor,ativo from servico_catalogo order by ativo desc,nome").query((r,n)->Map.<String,Object>of("id",r.getLong("id"),"nome",r.getString("nome"),"natureza",r.getString("natureza"),"valor",r.getBigDecimal("valor"),"ativo",r.getBoolean("ativo"))).list();}
 public Map<String,Object> salvar(Map<String,Object>b){String nome=String.valueOf(b.getOrDefault("nome","")).trim(),nat=String.valueOf(b.getOrDefault("natureza","")).trim();if(nome.length()<3)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe o nome do serviço");if(nat.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe a natureza fiscal");BigDecimal valor;try{valor=new BigDecimal(String.valueOf(b.getOrDefault("valor","0")));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Valor inválido");}if(valor.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Valor não pode ser negativo");Object id=b.get("id");if(id==null){jdbc.sql("insert into servico_catalogo(nome,natureza,valor) values(:n,:t,:v)").param("n",nome).param("t",nat).param("v",valor).update();}else jdbc.sql("update servico_catalogo set nome=:n,natureza=:t,valor=:v,ativo=:a,atualizado_em=now() where id=:id").param("n",nome).param("t",nat).param("v",valor).param("a",Boolean.parseBoolean(String.valueOf(b.getOrDefault("ativo",true)))).param("id",Long.parseLong(id.toString())).update();return listar().stream().filter(s->s.get("nome").equals(nome)).findFirst().orElseThrow();}
}
